// Generated by make types from the apb-catalog bundle's schemas/source-catalogue.schema.json.

export type CatalogueId = string;
export type CatalogueVersion = string;
export type SoftwareName = string;
export type Rule = string;
export type Level = string;
export type SoftwareVersionPattern = string;
export type Variants = RuleVariant[];
export type EntryId = string;
export type Rules = string[];
export type Level1 = string;
export type Location = "obs" | "layers" | "var" | "varm";
export type Name = string | null;
export type Table = string | null;
export type Role = string | null;
export type Prefix = string | null;
export type Basis = string;
export type Source = string | null;
export type Entries = SourceEntry[];

/**
 * Every reviewed rule variant of one vendor and the entries one consumer needs from it.
 */
export interface SourceCatalogue {
  catalogue_id: CatalogueId;
  catalogue_version: CatalogueVersion;
  software_name: SoftwareName;
  variants: Variants;
  entries: Entries;
}
/**
 * One packaged rule level, bound by the software version pattern its rule declares.
 */
export interface RuleVariant {
  rule: Rule;
  level: Level;
  software_version_pattern: SoftwareVersionPattern;
}
/**
 * The reviewed meaning of one retained field under the listed rule documents.
 */
export interface SourceEntry {
  entry_id: EntryId;
  rules: Rules;
  reference: Reference;
  qualifiers: Qualifiers;
  evidence: Evidence;
}
/**
 * Where one field lives in an APB result: by its APB output name, its role or a prefix.
 *
 * A ``varm`` field also names its feature-aligned table. A ``var`` field may be named by the
 * role the level's rule gives it, and an ``obs`` field of a sample annotation by the prefix of
 * its column name; both are bound to the column a level holds before they answer.
 */
export interface Reference {
  level: Level1;
  location: Location;
  name?: Name;
  table?: Table;
  role?: Role;
  prefix?: Prefix;
}
export interface Qualifiers {
  [k: string]: string;
}
/**
 * Why a reviewer assigned an entry's meaning.
 */
export interface Evidence {
  basis: Basis;
  source?: Source;
}
